import{_ as t,o as d,c as a,ag as o}from"./chunks/framework.DaCm-iTo.js";const u=JSON.parse('{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/level/commands.md","filePath":"en/modules/level/commands.md","lastUpdated":null}'),l={name:"en/modules/level/commands.md"};function s(n,e,c,i,r,p){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to &quot;Commands and Permissions&quot;">​</a></h1><p>Main command: <code>/emakilevel</code>; aliases: <code>/elv</code>, <code>/elevel</code>. Examples below use <code>/elv</code>.</p><p>Every subcommand first checks <code>emakilevel.use</code>. Administrative commands therefore require both <code>emakilevel.use</code> and their specific admin permission.</p><h2 id="player-commands" tabindex="-1">Player commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to &quot;Player commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/elv</code></td><td><code>emakilevel.use</code></td><td>View all loaded level types for yourself. Player-only.</td></tr><tr><td><code>/elv info [type]</code></td><td><code>emakilevel.use</code></td><td>View one level type. Without <code>type</code>, behaves like <code>/elv</code>.</td></tr><tr><td><code>/elv gui [type]</code></td><td><code>emakilevel.use</code></td><td>Open the level GUI. Without <code>type</code>, uses <code>config.yml &gt; primary_type</code>. Alias: <code>/elv open [type]</code>.</td></tr><tr><td><code>/elv levelup [type]</code></td><td><code>emakilevel.levelup</code></td><td>Manually level up one type. Without <code>type</code>, uses <code>config.yml &gt; primary_type</code>, default <code>main</code>. Alias: <code>/elv up [type]</code>.</td></tr><tr><td><code>/elv top [type]</code></td><td><code>emakilevel.top</code></td><td>View top 10 cached leaderboard entries for one type. Without <code>type</code>, uses the primary type.</td></tr><tr><td><code>/elv topgui [type]</code></td><td><code>emakilevel.top</code></td><td>Open the leaderboard GUI. Without <code>type</code>, uses the primary type. Alias: <code>/elv topopen [type]</code>. Player-only.</td></tr></tbody></table><p>Examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/elv</span></span>
<span class="line"><span>/elv info combat</span></span>
<span class="line"><span>/elv gui main</span></span>
<span class="line"><span>/elv levelup mining</span></span>
<span class="line"><span>/elv up main</span></span>
<span class="line"><span>/elv top combat</span></span>
<span class="line"><span>/elv topgui combat</span></span></code></pre></div><p>Manual level-up is controlled by <code>types/&lt;type&gt;.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">upgrade</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  manual_upgrade</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cost</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>If a type should only level up automatically from exp gain, keep <code>auto_upgrade: true</code> and set <code>manual_upgrade: false</code>.</p><h2 id="admin-commands" tabindex="-1">Admin commands <a class="header-anchor" href="#admin-commands" aria-label="Permalink to &quot;Admin commands&quot;">​</a></h2><p>These commands require <code>emakilevel.admin</code>. Command targets must be online because the command implementation resolves exact online player names.</p><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/elv giveexp &lt;player&gt; &lt;type&gt; &lt;amount&gt;</code></td><td><code>emakilevel.admin</code></td><td>Add exp to an online player. Alias: <code>addexp</code>. Auto-upgrade follows the type config.</td></tr><tr><td><code>/elv takeexp &lt;player&gt; &lt;type&gt; &lt;amount&gt;</code></td><td><code>emakilevel.admin</code></td><td>Remove current-level exp down to 0. Does not downgrade. Alias: <code>removeexp</code>.</td></tr><tr><td><code>/elv setexp &lt;player&gt; &lt;type&gt; &lt;amount&gt;</code></td><td><code>emakilevel.admin</code></td><td>Set current-level exp. Does not directly change level.</td></tr><tr><td><code>/elv addlevel &lt;player&gt; &lt;type&gt; &lt;amount&gt;</code></td><td><code>emakilevel.admin</code></td><td>Add levels, clamped between <code>start_level</code> and <code>max_level</code>. Alias: <code>givelevel</code>.</td></tr><tr><td><code>/elv takelevel &lt;player&gt; &lt;type&gt; &lt;amount&gt;</code></td><td><code>emakilevel.admin</code></td><td>Remove levels, not below <code>start_level</code>. Alias: <code>removelevel</code>.</td></tr><tr><td><code>/elv setlevel &lt;player&gt; &lt;type&gt; &lt;level&gt;</code></td><td><code>emakilevel.admin</code></td><td>Set level, clamped to the type range.</td></tr><tr><td><code>/elv reset &lt;player&gt; &lt;type&gt;</code></td><td><code>emakilevel.admin</code></td><td>Reset the type: level back to <code>start_level</code>, <code>exp</code> and <code>total_exp</code> to zero.</td></tr></tbody></table><p>Examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/elv giveexp Steve combat 250</span></span>
<span class="line"><span>/elv takeexp Steve mining 30</span></span>
<span class="line"><span>/elv setexp Steve main 0</span></span>
<span class="line"><span>/elv addlevel Steve main 5</span></span>
<span class="line"><span>/elv takelevel Steve combat 1</span></span>
<span class="line"><span>/elv setlevel Steve fishing 20</span></span>
<span class="line"><span>/elv reset Steve mining</span></span></code></pre></div><p>Operation differences:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Changes level</th><th>Changes current exp</th><th>Changes total exp</th><th>Notes</th></tr></thead><tbody><tr><td><code>giveexp</code></td><td>possibly</td><td>increases, then consumes requirement exp on level-up</td><td>increases</td><td>Auto-upgrade depends on type config.</td></tr><tr><td><code>takeexp</code></td><td>no</td><td>decreases to minimum 0</td><td>unchanged</td><td>Does not downgrade.</td></tr><tr><td><code>setexp</code></td><td>no</td><td>sets to value</td><td>unchanged</td><td>Useful for correcting current-level exp.</td></tr><tr><td><code>addlevel</code></td><td>yes</td><td>resets to 0</td><td>unchanged</td><td>Direct admin edit, no level-up rewards.</td></tr><tr><td><code>takelevel</code></td><td>yes</td><td>resets to 0</td><td>unchanged</td><td>Direct admin edit, no reward rollback.</td></tr><tr><td><code>setlevel</code></td><td>yes</td><td>resets to 0</td><td>unchanged</td><td>Direct admin edit.</td></tr><tr><td><code>reset</code></td><td>yes</td><td>resets to 0</td><td>resets to 0</td><td>Returns to the type&#39;s initial state.</td></tr></tbody></table><h2 id="reload-and-debug-commands" tabindex="-1">Reload and debug commands <a class="header-anchor" href="#reload-and-debug-commands" aria-label="Permalink to &quot;Reload and debug commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/elv reload</code></td><td><code>emakilevel.reload</code> or <code>emakilevel.admin</code></td><td>Save cached data, reload config, types, requirements, sources, language, PDC, and the attribute bridge, then sync online players.</td></tr><tr><td><code>/elv debug requirement &lt;type&gt; &lt;level&gt;</code></td><td><code>emakilevel.debug</code> or <code>emakilevel.admin</code></td><td>Show required exp and the source used for a target level.</td></tr><tr><td><code>/elv debug pdc &lt;player&gt;</code></td><td><code>emakilevel.debug</code> or <code>emakilevel.admin</code></td><td>Resync online player PDC. The implementation resyncs every online player.</td></tr><tr><td><code>/elv debug</code></td><td><code>emakilevel.debug</code> or <code>emakilevel.admin</code></td><td>Print the CoreLib debug status overview.</td></tr><tr><td><code>/elv debug status</code> / <code>on</code> / <code>off</code></td><td><code>emakilevel.debug</code> or <code>emakilevel.admin</code></td><td>Shared CoreLib debug switches: show status, enable all, disable all.</td></tr><tr><td><code>/elv debug player &lt;player&gt;</code></td><td><code>emakilevel.debug</code> or <code>emakilevel.admin</code></td><td>Toggle debug output for one online player.</td></tr><tr><td><code>/elv debug module &lt;module&gt;</code></td><td><code>emakilevel.debug</code> or <code>emakilevel.admin</code></td><td>Toggle a debug submodule. EmakiLevel contributes <code>common</code>; the shared CoreLib submodules <code>action</code>, <code>item_operation</code>, <code>variables</code>, <code>placeholder</code>, and <code>gui</code> are also available.</td></tr></tbody></table><p>Examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/elv reload</span></span>
<span class="line"><span>/elv debug requirement main 10</span></span>
<span class="line"><span>/elv debug requirement combat 35</span></span>
<span class="line"><span>/elv debug pdc Steve</span></span>
<span class="line"><span>/elv debug module common</span></span></code></pre></div><p><code>debug requirement</code> source values:</p><table tabindex="0"><thead><tr><th>Source</th><th>Meaning</th></tr></thead><tbody><tr><td><code>type.values</code></td><td>Exact target-level value in <code>types/&lt;type&gt;.yml &gt; requirement.values</code>.</td></tr><tr><td><code>type.formula</code></td><td>Type-specific formula in <code>types/&lt;type&gt;.yml &gt; requirement.formula</code>.</td></tr><tr><td><code>groups.&lt;group&gt;.values</code></td><td>Exact value in <code>requirements.yml &gt; groups.&lt;group&gt;.values</code>.</td></tr><tr><td><code>groups.&lt;group&gt;.formula</code></td><td>Formula in <code>requirements.yml &gt; groups.&lt;group&gt;.formula</code>.</td></tr><tr><td><code>global.values</code></td><td>Exact value in <code>requirements.yml &gt; global.values</code>.</td></tr><tr><td><code>global.formula</code></td><td>Formula in <code>requirements.yml &gt; global.formula</code>.</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Scope</th></tr></thead><tbody><tr><td><code>emakilevel.use</code></td><td><code>true</code></td><td>Main command and basic queries; also the registration permission of the root command. Checked before every subcommand.</td></tr><tr><td><code>emakilevel.levelup</code></td><td><code>true</code></td><td><code>/elv levelup</code> / <code>/elv up</code>.</td></tr><tr><td><code>emakilevel.top</code></td><td><code>true</code></td><td><code>/elv top</code> and <code>/elv topgui</code> / <code>/elv topopen</code>.</td></tr><tr><td><code>emakilevel.reload</code></td><td><code>op</code></td><td><code>/elv reload</code>.</td></tr><tr><td><code>emakilevel.debug</code></td><td><code>op</code></td><td><code>/elv debug requirement</code> and <code>/elv debug pdc</code>.</td></tr><tr><td><code>emakilevel.admin</code></td><td><code>op</code></td><td>Exp/level management commands; also accepted for reload/debug.</td></tr></tbody></table><p>LuckPerms examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lp group default permission set emakilevel.use true</span></span>
<span class="line"><span>/lp group default permission set emakilevel.levelup true</span></span>
<span class="line"><span>/lp group default permission set emakilevel.top true</span></span>
<span class="line"><span>/lp group admin permission set emakilevel.admin true</span></span>
<span class="line"><span>/lp group admin permission set emakilevel.reload true</span></span>
<span class="line"><span>/lp group admin permission set emakilevel.debug true</span></span></code></pre></div><h2 id="common-failure-reasons" tabindex="-1">Common failure reasons <a class="header-anchor" href="#common-failure-reasons" aria-label="Permalink to &quot;Common failure reasons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Reason ID</th><th>Common case</th></tr></thead><tbody><tr><td><code>player_not_found</code></td><td>Target player is offline/not found, or an API call lacks a valid UUID.</td></tr><tr><td><code>player_data_unavailable</code></td><td>Player level data is not loaded yet, or was already unloaded.</td></tr><tr><td><code>type_not_found</code></td><td>The <code>type</code> does not exist.</td></tr><tr><td><code>type_disabled</code></td><td>The type exists but <code>enabled: false</code>.</td></tr><tr><td><code>invalid_amount</code></td><td>Amount is invalid.</td></tr><tr><td><code>daily_cap_reached</code></td><td>The type&#39;s daily exp budget is exhausted; see <code>config.yml &gt; daily_caps</code>.</td></tr><tr><td><code>upgrade_disabled</code></td><td><code>upgrade.enabled: false</code>.</td></tr><tr><td><code>manual_upgrade_disabled</code></td><td>Player tried <code>/elv levelup</code>, but manual upgrade is disabled.</td></tr><tr><td><code>max_level</code></td><td>Already at <code>max_level</code>.</td></tr><tr><td><code>not_enough_exp</code></td><td>Current-level exp is insufficient.</td></tr><tr><td><code>not_enough_money</code></td><td>Economy cost is not affordable.</td></tr><tr><td><code>not_enough_material</code></td><td>Material cost is not available.</td></tr><tr><td><code>cost_compensation_failed</code></td><td>An upgrade cost was consumed, a later step failed, and refunding the cost also failed.</td></tr><tr><td><code>invalid_requirement</code></td><td>Requirement formula/config resolves to 0 or less.</td></tr></tbody></table><p>Asynchronous public-API writes may additionally return <code>api_unavailable</code>, <code>not_entity_owner</code>, <code>player_offline</code>, <code>owner_schedule_retired</code>, and <code>owner_schedule_rejected</code>. These come from thread-ownership scheduling, not from configuration.</p>`,30)])])}const h=t(l,[["render",s]]);export{u as __pageData,h as default};
